/// <reference path="./sigApi.AlarmInfoParameter.d.ts" />

declare namespace SigApi {
    interface AlarmInfo {
        /**
         * Gets the VarNo of the Alarm
         * 
         * @returns {number} The VarNo of the Alarm
         */
        getVarNo(): number
        /**
         * Gets the alarmnumber of the Alarm
         * alarmnumber is the value of the Client 'Config' from associated alarm object in LC2
         * 
         * @returns {number} The alarmnumber of the Alarm
         */
        getAlarmNr(): number
        /**
         * Gets the group of the Alarm
         * 
         * @returns {number} The group of the Alarm
         */
        getGroup(): number
        /**
         * Gets the stationId of the Alarm
         * 
         * @returns {number} The stationId of the Alarm
         */
        getStationId(): number
        /**
         * Gets the AlarmParameters of the Alarm
         * 
         * @returns {AlarmInfoParameter[]} The AlarmParameters of the Alarm
         */
        getParameters(): AlarmInfoParameter[]
    }
}
